                currentEnd = intervals[i][1];
            }
        }
        return removed;
    }
}

class Solution {
    public int eraseOverlapIntervals(int[][] intervals) {
        int n = intervals.length;
        java.util.Arrays.sort(intervals, (a, b) -> {
            int byEnd = Integer.compare(a[1], b[1]);
            return byEnd != 0 ? byEnd : Integer.compare(a[0], b[0]);
        });
        int[] dp = new int[n];
        java.util.Arrays.fill(dp, 1);
        int keep = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (intervals[j][1] <= intervals[i][0]) {
                    dp[i] = Math.max(dp[i], dp[j] + 1);
                }
            }
            keep = Math.max(keep, dp[i]);
        }
        return n - keep;
    }
}

class Solution {
    public int eraseOverlapIntervals(int[][] intervals) {
        int n = intervals.length;
        java.util.Arrays.sort(intervals, (a, b) -> {
            int byEnd = Integer.compare(a[1], b[1]);
            return byEnd != 0 ? byEnd : Integer.compare(a[0], b[0]);
        });
        int[] ends = new int[n];
        for (int i = 0; i < n; i++) {
            ends[i] = intervals[i][1];
        }
        int[] dp = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            int start = intervals[i - 1][0];
            int previous = upperBound(ends, start, i - 1);
            dp[i] = Math.max(dp[i - 1], dp[previous] + 1);
        }
        return n - dp[n];
    }

    private int upperBound(int[] ends, int target, int limit) {
        int left = 0;
        int right = limit;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (ends[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

import java.util.*;

class Solution {
    public int eraseOverlapIntervals(int[][] intervals) {
        java.util.Arrays.sort(intervals, (a, b) -> {
            int byEnd = Integer.compare(a[1], b[1]);
            return byEnd != 0 ? byEnd : Integer.compare(a[0], b[0]);
        });
        TreeMap<Integer, Integer> bestByEnd = new TreeMap<>();
        bestByEnd.put(Integer.MIN_VALUE, 0);
        for (int[] interval : intervals) {
            int bestBefore = bestByEnd.floorEntry(interval[0]).getValue();
            int candidate = bestBefore + 1;
            Map.Entry<Integer, Integer> atEnd = bestByEnd.floorEntry(interval[1]);
            if (candidate > atEnd.getValue()) {
                bestByEnd.put(interval[1], candidate);
                Map.Entry<Integer, Integer> later = bestByEnd.higherEntry(interval[1]);
                while (later != null && later.getValue() <= candidate) {
                    bestByEnd.remove(later.getKey());
                    later = bestByEnd.higherEntry(interval[1]);
                }
            }
        }
        return intervals.length - bestByEnd.lastEntry().getValue();
    }
}
